import java.sql.*;
import javax.servlet.http.*;

// Fix: use parameterized query with PreparedStatement to prevent SQL injection
public class GoodUserServlet extends HttpServlet {
    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws Exception {
        String username = req.getParameter("username"); // Untrusted input
        Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/db", "user", "pass");
        String query = "SELECT * FROM users WHERE name = ?"; // Parameter placeholder
        try (PreparedStatement stmt = conn.prepareStatement(query)) {
            stmt.setString(1, username); // Bind input as a parameter
            ResultSet rs = stmt.executeQuery();
            // process results safely
        }
    }
}
