import java.io.*;
import java.nio.file.Path;
import java.nio.file.Paths;
import javax.servlet.http.*;
import javax.servlet.annotation.WebServlet;

@WebServlet("/file")
public class SecureFileDownloadServlet extends HttpServlet {

    private static final String UPLOAD_DIRECTORY = "/uploads";

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String fileName = request.getParameter("filename");

        if (fileName == null || fileName.isEmpty()) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Filename parameter is required");
            return;
        }

        // Sanitize the filename to prevent directory traversal
        // Remove any path separators and invalid characters
        String safeFileName = Paths.get(fileName).getFileName().toString();

        // Construct the full path using a fixed base directory
        Path uploadDirPath = Paths.get(UPLOAD_DIRECTORY).toAbsolutePath().normalize();
        Path filePath = uploadDirPath.resolve(safeFileName).normalize();

        // Verify that the resolved path is still within the intended upload directory
        if (!filePath.startsWith(uploadDirPath)) {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Access denied");
            return;
        }

        File file = filePath.toFile();

        if (file.exists() && file.isFile()) {
            response.setContentType("application/octet-stream");
            response.setHeader("Content-Disposition", "attachment; filename=\"" + safeFileName + "\"");

            try (InputStream in = new FileInputStream(file)) {
                OutputStream out = response.getOutputStream();
                byte[] buffer = new byte[1024];
                int bytesRead;
                while ((bytesRead = in.read(buffer)) != -1) {
                    out.write(buffer, 0, bytesRead);
                }
                out.flush();
            }
        } else {
            response.sendError(HttpServletResponse.SC_NOT_FOUND, "File not found");
        }
    }
}
```

