```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

public class GoodExample {
    public void getUser(String username) throws Exception {
        // Connect to database
        Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "user", "pass");

        // FIXED: Use PreparedStatement with parameterized queries to prevent SQL injection.
        // The ? placeholder ensures that the input is treated strictly as data, not executable SQL code.
        String sql = "SELECT * FROM users WHERE username = ?";

        PreparedStatement pstmt = conn.prepareStatement(sql);
        pstmt.setString(1, username); // Safely set the parameter

        ResultSet rs = pstmt.executeQuery();

        if (rs.next()) {
            System.out.println("User found: " + rs.getString("username"));
        }

        // Close resources
        rs.close();
        pstmt.close();
        conn.close();
    }
}
```

