          "1": "Frequently applies incorrect or outdated technical practices, resulting in major rework.",
          "2": "Has foundational knowledge but makes avoidable technical errors and needs frequent direction.",
          "3": "Applies sound technical practices and produces correct, maintainable, and appropriately tested code.",
          "4": "Applies advanced techniques, optimizes solutions where appropriate, and raises the technical quality of the team.",
          "5": "Sets the technical standard and introduces practices that materially improve system reliability, performance, or velocity."
        }
      },
      {
        "id": "code_quality_and_design",
        "title": "Code Quality and Design",
        "description": "Writes clean, readable, maintainable, and well-structured code with appropriate design decisions.",
        "levels": {
          "1": "Code is hard to understand, poorly structured, and difficult to maintain without major rework.",
          "2": "Code is functional but often lacks clarity, consistency, or maintainability.",
          "3": "Code is readable, modular, well-organized, and aligned with team conventions.",
          "4": "Code is consistently clean, expressive, and demonstrates thoughtful design tradeoffs.",
          "5": "Code is exemplary, elegant, and serves as a model for maintainability, clarity, and sound design."
        }
      },
      {
        "id": "problem_solving_debugging",
        "title": "Problem Solving and Debugging",
        "description": "Analyzes problems, identifies root causes, and develops effective solutions or fixes.",
        "levels": {
          "1": "Struggles to diagnose issues and often escalates without meaningful analysis.",
          "2": "Can solve familiar problems but requires frequent help with unfamiliar or complex issues.",
          "3": "Independently diagnoses common and moderately complex issues and implements sound fixes.",
          "4": "Quickly identifies root causes in complex systems and develops durable, effective solutions.",
          "5": "Consistently solves highly complex or ambiguous problems and prevents recurrence through systemic improvements."
        }
      },
      {
        "id": "architecture_and_systems_thinking",
        "title": "Architecture and Systems Thinking",
        "description": "Makes appropriate technical and architectural decisions within the context of product goals and constraints.",
        "levels": {
          "1": "Lacks awareness of broader system impact and makes decisions that create significant risk.",
          "2": "Understands immediate task context but has limited understanding of wider system implications.",
          "3": "Considers system impact, scalability, and maintainability in routine decisions.",
          "4": "Makes well-reasoned architectural or design decisions and proactively addresses technical debt or risk.",
          "5": "Shapes the technical direction of the system and delivers decisions with significant long-term impact."
        }
      },
      {
        "id": "collaboration_and_communication",
        "title": "Collaboration and Communication",
        "description": "Communicates clearly, collaborates effectively, and contributes positively to team dynamics.",
        "levels": {
          "1": "Communicates unclearly or inconsistently and struggles to collaborate with others.",
          "2": "Participates in collaboration but often requires prompting, clarification, or follow-up.",
          "3": "Communicates clearly, provides useful updates, and collaborates constructively with peers.",
          "4": "Proactively shares knowledge, gives and receives feedback, and strengthens team effectiveness.",
          "5": "Is a trusted collaborator who aligns stakeholders, mentors peers, and elevates the team through communication."
        }
      },
      {
        "id": "ownership_and_impact",
        "title": "Ownership and Impact",
        "description": "Takes ownership of outcomes, drives work forward, and delivers value to the product or organization.",
        "levels": {
          "1": "Avoids ownership and has minimal positive impact on deliverables or outcomes.",
          "2": "Completes assigned tasks but requires frequent prompting and has limited impact beyond immediate scope.",
          "3": "Owns assigned work from start to finish and delivers reliable, measurable value.",
          "4": "Proactively expands scope to address gaps, risks, or opportunities that improve outcomes.",
          "5": "Drives high-impact initiatives end to end and consistently produces results that move key business or product metrics."
        }
      },
      {
        "id": "learning_and_adaptability",
        "title": "Learning and Adaptability",
        "description": "Learns new skills, embraces feedback, and adapts to changing requirements or technologies.",
        "levels": {
          "1": "Resists new information, feedback, or change and shows little growth.",
          "2": "Can learn when required but often struggles to apply new knowledge independently.",
          "3": "Learns effectively, applies feedback, and adapts to changing priorities and technologies.",
          "4": "Quickly masters new areas and helps the team adapt to new tools, processes, or requirements.",
          "5": "Continuously deepens expertise, anticipates change, and drives high-leverage improvements through learning."
        }
      },
      {
        "id": "execution_and_delivery",
        "title": "Execution and Delivery",
        "description": "Plans work, estimates effort, meets commitments, and delivers quality results on time.",
        "levels": {
          "1": "Frequently misses commitments and delivers incomplete or low-quality work.",
          "2": "Meets some commitments but often has poor planning, estimation, or follow-through.",
          "3": "Reliably delivers committed work with appropriate quality and timing.",
          "4": "Consistently exceeds commitments or improves estimates, quality, and speed of delivery.",
          "5": "Delivers exceptional results under complexity or uncertainty and sets the standard for dependable execution."
        }
      }
    ],
    "usage_instructions": "Rate each criterion on the 1-5 scale. Use concrete examples from the review period to support each rating. Focus on sustained behavior and impact, not isolated incidents. The overall performance rating should reflect the pattern across criteria, with weighting appropriate to the role level."
  }
}

