<script>
(function(){
  var rm = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* reading progress */
  var bar = document.getElementById('pbar');
  function onScroll(){
    var h = document.documentElement;
    var max = h.scrollHeight - h.clientHeight;
    bar.style.width = (max > 0 ? (h.scrollTop / max) * 100 : 0) + '%';
  }
  window.addEventListener('scroll', onScroll, {passive:true});
  onScroll();

  /* masthead line-mask reveal */
  window.requestAnimationFrame(function(){ setTimeout(function(){ document.body.classList.add('loaded'); }, 60); });

  /* plates: line-by-line reveal */
  var plates = Array.prototype.slice.call(document.querySelectorAll('.plate'));
  if (rm || !('IntersectionObserver' in window)) {
    plates.forEach(function(p){ p.classList.add('in'); });
  } else {
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if (e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); }
      });
    }, {threshold: 0.18});
    plates.forEach(function(p){ io.observe(p); });
  }

  /* sticky index: active tracking */
  var links = Array.prototype.slice.call(document.querySelectorAll('.index-list a'));
  function setAct(id){ links.forEach(function(l){ l.classList.toggle('act', l.hash === '#' + id); }); }
  if ('IntersectionObserver' in window) {
    var io2 = new IntersectionObserver(function(entries){
      entries.forEach(function(e){ if (e.isIntersecting) setAct(e.target.id); });
    }, {rootMargin: '-42% 0px -52% 0px'});
    plates.forEach(function(p){ io2.observe(p); });
  }
  links.forEach(function(l){
    l.addEventListener('click', function(){ setAct(l.hash.slice(1)); });
  });

  /* a verse at random */
  document.getElementById('randomBtn').addEventListener('click', function(){
    var p = plates[Math.floor(Math.random() * plates.length)];
    p.scrollIntoView({behavior: rm ? 'auto' : 'smooth', block: 'start'});
    p.classList.remove('flash'); void p.offsetWidth; p.classList.add('flash');
    setAct(p.id);
  });

  /* recite (Web Speech, graceful fallback) */
  var current = null;
  document.querySelectorAll('.recite').forEach(function(btn){
    btn.addEventListener('click', function(){
      if (!('speechSynthesis' in window)){
        btn.textContent = 'No voice here';
        setTimeout(function(){ btn.textContent = 'Recite'; }, 1600);
        return;
      }
      var text = btn.closest('.plate').querySelector('.verse').innerText;
      if (current){ try { speechSynthesis.cancel(); } catch(e){} current = null; }
      var u = new SpeechSynthesisUtterance(text);
      u.rate = 0.95; u.pitch = 1;
      current = u;
      u.onend = u.onerror = function(){
        if (current === u){ current = null; btn.classList.remove('speaking'); btn.textContent = 'Recite'; }
      };
      btn.classList.add('speaking'); btn.textContent = 'Speaking…';
      speechSynthesis.speak(u);
    });
  });
  window.addEventListener('beforeunload', function(){ if ('speechSynthesis' in window) speechSynthesis.cancel(); });
})();
</script>
</body>
</html>
```

Highlights: a broadsheet masthead with a rotating "one penny" seal and a scan of the AABBA meter, a sticky contents index that tracks your scroll position, a "verse at random" button, per-plate **Recite** buttons (Web Speech API), line-by-line verse reveals, slow breathing zoom on the oval engravings, and paper-grain texture — all gated behind `prefers-reduced-motion`. The required keywords appear in Plate VII (the economist), Plate XIV (the Jurgen), and the errata/colophon (the unpaid bill).

